"use client";

import { useState } from "react";
import { Star } from "lucide-react";

const Page = () => {
  const [rating, setRating] = useState(0);
  const [hover, setHover] = useState(0);

  const currentRating = hover || rating;

  return (
    <main className="min-h-screen bg-slate-50 flex items-center justify-center p-5">
      <section className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-xl shadow-slate-200/60">
        {/* Header */}
        <p className="text-sm font-semibold uppercase tracking-[0.2em] text-blue-600">
          Rating
        </p>

        <h1 className="mt-2 text-2xl font-bold text-slate-800">
          How was your experience?
        </h1>

        <p className="mt-2 text-sm text-slate-500">
          Select a star to rate your experience.
        </p>

        {/* Stars */}
        <div
          className="mt-8 flex justify-center gap-2"
          onMouseLeave={() => setHover(0)}
        >
          {Array.from({ length: 5 }, (_, index) => {
            const starValue = index + 1;
            const isFilled = currentRating >= starValue;

            return (
              <button
                key={starValue}
                type="button"
                aria-label={`Rate ${starValue} out of 5`}
                onClick={() => setRating(starValue)}
                onMouseEnter={() => setHover(starValue)}
                className="rounded-lg p-1 outline-none transition-transform duration-150"
              >
                <Star
                  size={36}
                  className={`transition-colors duration-150 ${
                    isFilled
                      ? "fill-amber-400 text-amber-400"
                      : "text-slate-300"
                  }`}
                />
              </button>
            );
          })}
        </div>
      </section>
    </main>
  );
};

export default Page;

"use client";

import { useState } from "react";

const Page = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const [usernameError, setUsernameError] = useState("");
  const [passwordError, setPasswordError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    let isValid = true;

    if (username.trim().length < 3) {
      setUsernameError("Username must be at least 3 characters long");
      isValid = false;
    } else {
      setUsernameError("");
    }

    if (password.length < 6) {
      setPasswordError("Password must be at least 6 characters long");
      isValid = false;
    } else {
      setPasswordError("");
    }

    if (!isValid) {
      return;
    }

    console.log("Username:", username);
    console.log("Password:", password);

    setUsername("");
    setPassword("");
  };

  return (
    <main className="min-h-screen bg-slate-50 flex items-center justify-center p-5">
      <form
        onSubmit={handleSubmit}
        className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-8 shadow-xl shadow-slate-200/60"
      >
        {/* Header */}
        <div className="mb-8">
          <p className="text-sm font-semibold uppercase tracking-[0.2em] text-blue-600">
            Account
          </p>

          <h1 className="mt-2 text-3xl font-bold text-slate-800">
            Create Account
          </h1>

          <p className="mt-2 text-sm text-slate-500">
            Enter your details to create your account.
          </p>
        </div>

        <div className="space-y-5">
          {/* Username */}
          <div>
            <label
              htmlFor="username"
              className="mb-2 block text-sm font-medium text-slate-700"
            >
              Username
            </label>

            <input
              id="username"
              type="text"
              placeholder="Enter your username"
              value={username}
              onChange={(e) => {
                setUsername(e.target.value);

                if (usernameError) {
                  setUsernameError("");
                }
              }}
              className={`w-full rounded-xl border bg-white px-4 py-3 text-sm text-slate-700 outline-none transition ${
                usernameError
                  ? "border-red-400 focus:ring-4 focus:ring-red-100"
                  : "border-slate-200 focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
              }`}
            />

            {usernameError && (
              <p className="mt-2 text-sm text-red-500">{usernameError}</p>
            )}
          </div>

          {/* Password */}
          <div>
            <label
              htmlFor="password"
              className="mb-2 block text-sm font-medium text-slate-700"
            >
              Password
            </label>

            <input
              id="password"
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);

                if (passwordError) {
                  setPasswordError("");
                }
              }}
              className={`w-full rounded-xl border bg-white px-4 py-3 text-sm text-slate-700 outline-none transition ${
                passwordError
                  ? "border-red-400 focus:ring-4 focus:ring-red-100"
                  : "border-slate-200 focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
              }`}
            />

            {passwordError && (
              <p className="mt-2 text-sm text-red-500">{passwordError}</p>
            )}
          </div>

          {/* Submit */}
          <button
            type="submit"
            className="w-full rounded-xl bg-blue-600 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-500/20 transition-all duration-200 hover:bg-blue-700 hover:shadow-blue-500/30 active:scale-[0.98]"
          >
            Sign Up
          </button>
        </div>
      </form>
    </main>
  );
};

export default Page;

"use client";

import { useState } from "react";
import { Check, ChevronLeft, ChevronRight } from "lucide-react";

const Page = () => {
  const [step, setStep] = useState(1);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    age: "",
    username: "",
    password: "",
  });

  const [error, setError] = useState("");

  const steps = [
    {
      number: 1,
      title: "Personal",
    },
    {
      number: 2,
      title: "Account",
    },
    {
      number: 3,
      title: "Review",
    },
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

    setError("");
  };

  const handleNext = () => {
    setError("");

    if (step === 1) {
      if (!formData.name.trim() || !formData.email.trim() || !formData.age) {
        setError("Please fill in all personal information.");
        return;
      }

      if (!formData.email.includes("@")) {
        setError("Please enter a valid email address.");
        return;
      }

      if (Number(formData.age) < 1) {
        setError("Please enter a valid age.");
        return;
      }
    }

    if (step === 2) {
      if (!formData.username.trim() || !formData.password) {
        setError("Please fill in all account information.");
        return;
      }

      if (formData.username.length < 3) {
        setError("Username must be at least 3 characters.");
        return;
      }

      if (formData.password.length < 6) {
        setError("Password must be at least 6 characters.");
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  const handlePrevious = () => {
    setError("");
