"use client";

import axios from "axios";
import { useEffect, useState } from "react";
import { Mail, MapPin, Loader2, AlertCircle } from "lucide-react";

interface Address {
  city: string;
  zipcode: string;
}

interface User {
  id: number;
  name: string;
  email: string;
  address: Address;
}

const Page = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        setLoading(true);
        setError(null);

        const res = await axios.get<User[]>(
          "https://jsonplaceholder.typicode.com/users"
        );

        setUsers(res.data);
      } catch (error: unknown) {
        if (axios.isAxiosError(error)) {
          setError(error.message);
        } else if (error instanceof Error) {
          setError(error.message);
        } else {
          setError("Something went wrong");
        }
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, []);

  // Loading State
  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="size-10 animate-spin text-blue-600" />

          <p className="text-sm font-medium text-slate-500">
            Loading users...
          </p>
        </div>
      </main>
    );
  }

  // Error State
  if (error) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-50 p-5">
        <div className="max-w-md rounded-2xl border border-red-100 bg-white p-8 text-center shadow-lg">
          <AlertCircle className="mx-auto size-10 text-red-500" />

          <h1 className="mt-4 text-xl font-bold text-slate-800">
            Something went wrong
          </h1>

          <p className="mt-2 text-sm text-red-500">
            {error}
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-50 px-5 py-10 sm:px-8">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-8">
          <p className="text-sm font-semibold uppercase tracking-wider text-blue-600">
            API Data
          </p>

          <h1 className="mt-2 text-3xl font-bold text-slate-800">
            Users
          </h1>

          <p className="mt-2 text-sm text-slate-500">
            {users.length} users fetched successfully
          </p>
        </div>

        {/* Users Grid */}
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {users.map((user) => (
            <article
              key={user.id}
              className="group rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-lg"
            >
              {/* Avatar */}
              <div className="flex size-12 items-center justify-center rounded-full bg-blue-50 text-lg font-bold text-blue-600">
                {user.name.charAt(0).toUpperCase()}
              </div>

              {/* Name */}
              <h2 className="mt-4 text-lg font-bold text-slate-800">
                {user.name}
              </h2>

              {/* Email */}
              <div className="mt-3 flex items-center gap-2 text-sm text-slate-500">
                <Mail className="size-4 shrink-0 text-blue-500" />

                <span className="truncate">
                  {user.email}
                </span>
              </div>

              {/* Address */}
              <div className="mt-3 flex items-start gap-2 text-sm text-slate-500">
