"use client";

import { useRef, useState } from "react";
import { ShieldCheck } from "lucide-react";

const OTP_LENGTH = 6;

const Page = () => {
  const [otp, setOtp] = useState<string[]>(
    Array(OTP_LENGTH).fill(""),
  );
  const [error, setError] = useState("");

  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>,
    index: number,
  ) => {
    const value = e.target.value;

    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];

    // Only take one digit
    newOtp[index] = value.slice(-1);

    setOtp(newOtp);
    setError("");

    if (value && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (
    e: React.KeyboardEvent<HTMLInputElement>,
    index: number,
  ) => {
    if (e.key === "Backspace") {
      if (!otp[index] && index > 0) {
        inputRefs.current[index - 1]?.focus();
      }
    }
  };

  const handlePaste = (
    e: React.ClipboardEvent<HTMLInputElement>,
  ) => {
    e.preventDefault();

    const pastedData = e.clipboardData
      .getData("text")
      .replace(/\D/g, "")
      .slice(0, OTP_LENGTH);

    if (!pastedData) return;

    const newOtp = Array(OTP_LENGTH).fill("");

    pastedData.split("").forEach((digit, index) => {
      newOtp[index] = digit;
    });

    setOtp(newOtp);
    setError("");

    const nextIndex = Math.min(
      pastedData.length,
      OTP_LENGTH - 1,
    );

    inputRefs.current[nextIndex]?.focus();
  };

  const handleSubmit = () => {
    const finalOtp = otp.join("");

    if (finalOtp.length !== OTP_LENGTH) {
      setError(`Please enter the complete ${OTP_LENGTH}-digit OTP.`);
      return;
    }

    setError("");
    console.log("OTP:", finalOtp);

    alert(`OTP Verified: ${finalOtp}`);
  };

  return (
    <main className="flex min-h-screen items-center justify-center bg-slate-50 p-5">
      <section className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-6 shadow-xl shadow-slate-200/60 sm:p-8">
        {/* Icon */}
        <div className="mx-auto flex size-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-600">
          <ShieldCheck className="size-7" />
        </div>

        {/* Header */}
        <div className="mt-5 text-center">
          <p className="text-sm font-semibold uppercase tracking-[0.2em] text-blue-600">
            Verification
          </p>

          <h1 className="mt-2 text-2xl font-bold text-slate-800">
            Enter OTP
          </h1>

          <p className="mt-2 text-sm leading-6 text-slate-500">
            Enter the 6-digit verification code sent to you.
          </p>
        </div>

        {/* OTP Inputs */}
        <div className="mt-8 flex justify-center gap-2 sm:gap-3">
          {otp.map((value, index) => (
            <input
              key={index}
              ref={(element) => {
                inputRefs.current[index] = element;
              }}
              type="text"
              inputMode="numeric"
              maxLength={1}
              value={value}
              onChange={(e) => handleChange(e, index)}
              onKeyDown={(e) => handleKeyDown(e, index)}
              onPaste={handlePaste}
              className={`h-11 w-10 rounded-xl border text-center text-lg font-bold text-slate-800 outline-none transition sm:h-12 sm:w-12 ${
                value
                  ? "border-blue-500 bg-blue-50"
                  : "border-slate-200 bg-white"
              } focus:border-blue-500 focus:ring-4 focus:ring-blue-100`}
            />
          ))}
        </div>

        {/* Error */}
        {error && (
          <p className="mt-4 text-center text-sm font-medium text-red-500">
            {error}
          </p>
        )}

        {/* Button */}
        <button
          type="button"
          onClick={handleSubmit}
          className="mt-6 w-full rounded-xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-500/20 transition hover:bg-blue-700 active:scale-[0.98]"
        >
          Verify OTP
        </button>

        <p className="mt-5 text-center text-sm text-slate-500">
          Didn't receive the code?{" "}
          <button
            type="button"
            className="font-semibold text-blue-600 hover:text-blue-700"
          >
            Resend OTP
          </button>
        </p>
      </section>
    </main>
  );
};

export default Page;

