    info: {
      container: "border-blue-200 bg-blue-50",
      icon: "text-blue-600",
      title: "text-blue-800",
      Icon: Info,
    },
  };

  const currentToast = toastStyles[toast.type];
  const Icon = currentToast.Icon;

  return (
    <div
      className={`flex w-full min-w-[320px] items-center gap-3 rounded-xl border p-4 shadow-lg shadow-slate-200/50 ${currentToast.container}`}
